from flask import Flask, request, jsonify, Response, redirect, url_for
from dataclasses import dataclass, asdict
from datetime import datetime, timedelta, timezone
from pathlib import Path
import csv
import io
import json
import os
import uuid

app = Flask(__name__)
DATA_FILE = Path('/workspace/sprat_data.json')

ROLE_ORDER = {'guest': 0, 'analyst': 1, 'manager': 2, 'admin': 3}


def now():
    return datetime.now(timezone.utc).isoformat()


def load_data():
    if DATA_FILE.exists():
        return json.loads(DATA_FILE.read_text())
    return {
        'users': {
            'admin': {'role': 'admin', 'projects': ['default'], 'approved_network': True, 'trusted_device': True},
            'manager': {'role': 'manager', 'projects': ['default'], 'approved_network': True, 'trusted_device': True},
            'analyst': {'role': 'analyst', 'projects': ['default'], 'approved_network': True, 'trusted_device': True},
            'guest': {'role': 'guest', 'projects': ['default'], 'approved_network': True, 'trusted_device': True},
        },
        'projects': {
            'default': {'sensitivity': 'low', 'approved_network_only': False, 'trusted_device_required': False, 'extra_approval_for_remote': False},
            'sensitive': {'sensitivity': 'high', 'approved_network_only': True, 'trusted_device_required': True, 'extra_approval_for_remote': True},
        },
        'artifacts': [],
        'traces': [],
        'analyses': [],
        'audit': [],
        'exceptions': [],
    }


def save_data(data):
    DATA_FILE.write_text(json.dumps(data, indent=2))


def get_user(data):
    username = request.headers.get('X-User', 'guest')
    user = data['users'].get(username)
    if not user:
        user = data['users']['guest']
    return username, user


def require_role(user, minimum):
    return ROLE_ORDER[user['role']] >= ROLE_ORDER[minimum]


def log_audit(data, action, obj_type, obj_id, before=None, after=None):
    data['audit'].append({'ts': now(), 'action': action, 'type': obj_type, 'id': obj_id, 'before': before, 'after': after})


def visible_item(item, user, project):
    if user['role'] == 'guest' and item.get('sensitivity') in ('high', 'secret'):
        return False
    if project and project.get('sensitivity') == 'high' and user['role'] == 'guest':
        return False
    return True


def redacted(item, user):
    item = dict(item)
    if user['role'] == 'guest':
        item.pop('notes', None)
        item.pop('draft_comments', None)
        item.pop('personal_data', None)
    return item


def get_project(data, project_id):
    return data['projects'].get(project_id)


def ensure_can_access_project(user, project):
    if not project:
        return False, 'unknown project'
    if user['role'] == 'guest' and project['sensitivity'] == 'high':
        return False, 'guest cannot access sensitive project'
    return True, ''


@app.get('/')
def index():
    return Response('''<html><body><h1>SPRAT</h1><p>Use the API endpoints documented at /api.</p></body></html>''', mimetype='text/html')


@app.get('/api')
def api_root():
    return jsonify({
        'endpoints': ['/api/items', '/api/traces', '/api/compare', '/api/export', '/api/audit', '/api/validate', '/api/exceptions']
    })


@app.post('/api/items')
def create_item():
    data = load_data()
    username, user = get_user(data)
    payload = request.get_json(force=True)
    project = get_project(data, payload.get('project', 'default'))
    ok, msg = ensure_can_access_project(user, project)
    if not ok:
        return jsonify({'error': msg}), 403
    item = {
        'id': str(uuid.uuid4()),
        'project': payload.get('project', 'default'),
        'type': payload.get('type'),
        'title': payload.get('title', ''),
        'description': payload.get('description', ''),
        'classification': payload.get('classification', 'uncategorized'),
        'status': payload.get('status', 'draft'),
        'source_policy_reference': payload.get('source_policy_reference'),
        'policy_excerpt': payload.get('policy_excerpt'),
        'rationale': payload.get('rationale'),
        'actor': payload.get('actor'),
        'trigger': payload.get('trigger'),
        'outcome': payload.get('outcome'),
        'derived_from': payload.get('derived_from', []),
        'trace_links': payload.get('trace_links', []),
        'created_by': username,
        'created_at': now(),
        'updated_at': now(),
        'version': 1,
        'sensitivity': payload.get('sensitivity', 'normal'),
    }
    data['artifacts'].append(item)
    log_audit(data, 'create', 'item', item['id'], after=item)
    save_data(data)
    return jsonify(item), 201


@app.get('/api/items')
def list_items():
    data = load_data()
    _, user = get_user(data)
    project_id = request.args.get('project')
    items = [redacted(i, user) for i in data['artifacts'] if (not project_id or i['project'] == project_id)]
    return jsonify(items)


@app.post('/api/traces')
def create_trace():
    data = load_data()
    username, user = get_user(data)
    payload = request.get_json(force=True)
    trace = {
        'id': str(uuid.uuid4()),
        'source_id': payload['source_id'],
        'target_id': payload['target_id'],
        'kind': payload.get('kind', 'derived-from'),
        'primary': bool(payload.get('primary', False)),
        'created_by': username,
        'created_at': now(),
        'approved': False,
    }
    if user['role'] == 'guest':
        return jsonify({'error': 'guest cannot create traces'}), 403
    data['traces'].append(trace)
    log_audit(data, 'create', 'trace', trace['id'], after=trace)
    save_data(data)
    return jsonify(trace), 201


@app.get('/api/compare')
def compare():
    data = load_data()
    a = request.args.get('a')
    b = request.args.get('b')
    items_a = [i for i in data['artifacts'] if i['project'] == a]
    items_b = [i for i in data['artifacts'] if i['project'] == b]
    map_a = {i['title']: i for i in items_a}
    map_b = {i['title']: i for i in items_b}
    shared = sorted(set(map_a) & set(map_b))
    only_a = sorted(set(map_a) - set(map_b))
    only_b = sorted(set(map_b) - set(map_a))
    return jsonify({'shared_titles': shared, 'only_in_a': only_a, 'only_in_b': only_b})


@app.get('/api/audit')
def audit():
    data = load_data()
    return jsonify(data['audit'])


@app.get('/api/validate')
def validate():
    data = load_data()
    warnings = []
    item_ids = {i['id'] for i in data['artifacts']}
    for item in data['artifacts']:
        if item['type'] == 'requirement' and item.get('source_policy_reference') and not item.get('trace_links'):
            warnings.append({'item': item['id'], 'issue': 'requirement claims policy source but has no trace links'})
        if not item.get('classification'):
            warnings.append({'item': item['id'], 'issue': 'missing classification'})
    for tr in data['traces']:
        if tr['source_id'] not in item_ids or tr['target_id'] not in item_ids:
            warnings.append({'trace': tr['id'], 'issue': 'broken link'})
    return jsonify({'warnings': warnings})


@app.post('/api/export')
def export():
    data = load_data()
    username, user = get_user(data)
    payload = request.get_json(force=True)
    fmt = payload.get('format', 'json')
    project = payload.get('project', 'default')
    if user['role'] == 'guest':
        return jsonify({'error': 'raw exports restricted'}), 403
    items = [i for i in data['artifacts'] if i['project'] == project]
    if fmt == 'csv':
        out = io.StringIO()
        writer = csv.DictWriter(out, fieldnames=['id', 'type', 'title', 'description', 'classification', 'created_by', 'created_at'])
        writer.writeheader()
        for i in items:
            writer.writerow({k: i.get(k, '') for k in writer.fieldnames})
        return Response(out.getvalue(), mimetype='text/csv')
    return jsonify({'items': items, 'traces': [t for t in data['traces'] if any(i['id'] == t['source_id'] or i['id'] == t['target_id'] for i in items)]})


@app.post('/api/exceptions')
def exceptions():
    data = load_data()
    username, user = get_user(data)
    payload = request.get_json(force=True)
    exc = {
        'id': str(uuid.uuid4()),
        'reason': payload.get('reason', ''),
        'workaround': payload.get('workaround', ''),
        'target': payload.get('target', ''),
        'expires_at': payload.get('expires_at'),
        'created_by': username,
        'created_at': now(),
        'approved': False,
    }
    if not require_role(user, 'manager'):
        return jsonify({'error': 'manager approval required'}), 403
    data['exceptions'].append(exc)
    log_audit(data, 'create', 'exception', exc['id'], after=exc)
    save_data(data)
    return jsonify(exc), 201


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=int(os.environ.get('PORT', '8000')))
